    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(++i);
            switch (nextChar) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
