static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        if (year < 1000 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid timeBucket format");
        }

        int daysInMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
            daysInMonth[1] = 29; // Leap year
        }
        if (day > daysInMonth[month - 1]) {
            throw new IllegalArgumentException("Invalid day for the given month and year");
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        int newDayOfYear = (dayOfYear / dayStep) * dayStep + 1;

        int newMonth = 0;
        int newDay = newDayOfYear;
        for (int i = 0; i < 12; i++) {
            if (newDay > daysInMonth[i]) {
                newDay -= daysInMonth[i];
                newMonth++;
            } else {
                break;
            }
        }

        newMonth += 1; // Convert zero-based month to one-based

        return year * 10000 + newMonth * 100 + newDay;
    } catch (Exception e) {
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

