        int offset = 0;
        LinkedBuffer current = lb;

        while (offset < length) {
            int remaining = current.limit() - current.offset();
            if (remaining == 0) {
                current = current.next = session.nextBuffer();
                remaining = current.limit() - current.offset();
            }

            int i = offset;
            while (i < length && remaining > 0) {
                char c = str.charAt(i);
                if (c < 0x80) {
